package main

import (
	"fmt"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail constructs an HTML-formatted email body for user feedback.
// It takes the sender address, recipient address, username, subject, and feedback content.
// Returns the complete email body as a string and any error encountered.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate inputs
	if fromAddr == "" || toAddr == "" || userName == "" || subject == "" || feedbackContent == "" {
		return "", fmt.Errorf("all parameters must be non-empty")
	}

	// Construct the HTML email body
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>User Feedback</title>
</head>
<body>
    <h2>User Feedback Submission</h2>
    <table border="1" cellpadding="10" cellspacing="0" style="border-collapse: collapse; width: 100%%;">
        <tr>
            <th style="text-align: left; background-color: #f2f2f2;">Field</th>
            <th style="text-align: left; background-color: #f2f2f2;">Value</th>
        </tr>
        <tr>
            <td><strong>Username</strong></td>
            <td>%s</td>
        </tr>
        <tr>
            <td><strong>Subject</strong></td>
            <td>%s</td>
        </tr>
        <tr>
            <td><strong>Feedback Content</strong></td>
            <td>%s</td>
        </tr>
    </table>
</body>
</html>`, escapeHTML(userName), escapeHTML(subject), escapeHTML(feedbackContent))

	// Construct the full email message with headers
	headers := make(map[string]string)
	headers["From"] = fromAddr
	headers["To"] = toAddr
	headers["Subject"] = subject
	headers["MIME-Version"] = "1.0"
	headers["Content-Type"] = "text/html; charset=UTF-8"

	var headerStr strings.Builder
	for key, value := range headers {
		headerStr.WriteString(fmt.Sprintf("%s: %s\r\n", key, value))
	}
	headerStr.WriteString("\r\n") // Empty line separates headers from body

	emailBody = headerStr.String() + htmlBody

	return emailBody, nil
}

// escapeHTML escapes special HTML characters to prevent XSS and ensure proper rendering
func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

func main() {
	// Example usage
	from := "noreply@example.com"
	to := "support@example.com"
	username := "John Doe"
	subject := "Feature Request"
	feedback := "I would like to see a dark mode option in the application."

	emailBody, err := BuildFeedbackEmail(from, to, username, subject, feedback)
	if err != nil {
		fmt.Printf("Error building email: %v\n", err)
		return
	}

	fmt.Println("Generated Email Body:")
	fmt.Println(emailBody)

	// Note: To actually send the email, you would use smtp.SendMail
	// Example (not executed here):
	// auth := smtp.PlainAuth("", "username", "password", "smtp.example.com")
	// err = smtp.SendMail("smtp.example.com:587", auth, from, []string{to}, []byte(emailBody))
}

