package main

import (
	"fmt"
	"strings"
)

// BuildFeedbackEmail generates an HTML-formatted email body for user feedback.
// It collects user-submitted feedback information and formats it into an email
// that can be sent to the customer support team.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate required fields
	if fromAddr == "" {
		return "", fmt.Errorf("from address cannot be empty")
	}
	if toAddr == "" {
		return "", fmt.Errorf("to address cannot be empty")
	}
	if userName == "" {
		return "", fmt.Errorf("user name cannot be empty")
	}
	if subject == "" {
		return "", fmt.Errorf("subject cannot be empty")
	}
	if feedbackContent == "" {
		return "", fmt.Errorf("feedback content cannot be empty")
	}

	// Escape HTML special characters in user-provided content to prevent XSS
	escapedUserName := htmlEscape(userName)
	escapedSubject := htmlEscape(subject)
	escapedFeedbackContent := htmlEscape(feedbackContent)

	// Construct the email headers and body
	var builder strings.Builder

	// Email headers
	builder.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	builder.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	builder.WriteString(fmt.Sprintf("Subject: User Feedback: %s\r\n", escapedSubject))
	builder.WriteString("MIME-Version: 1.0\r\n")
	builder.WriteString("Content-Type: text/html; charset=UTF-8\r\n")
	builder.WriteString("\r\n")

	// HTML body
	builder.WriteString("<!DOCTYPE html>\n")
	builder.WriteString("<html>\n")
	builder.WriteString("<head>\n")
	builder.WriteString("    <meta charset=\"UTF-8\">\n")
	builder.WriteString("    <title>User Feedback</title>\n")
	builder.WriteString("</head>\n")
	builder.WriteString("<body>\n")
	builder.WriteString("    <h2>User Feedback Submission</h2>\n")
	builder.WriteString("    <table border=\"1\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse: collapse; width: 100%;\">\n")
	builder.WriteString("        <tr>\n")
	builder.WriteString("            <td><strong>User Name:</strong></td>\n")
	builder.WriteString(fmt.Sprintf("            <td>%s</td>\n", escapedUserName))
	builder.WriteString("        </tr>\n")
	builder.WriteString("        <tr>\n")
	builder.WriteString("            <td><strong>Subject:</strong></td>\n")
	builder.WriteString(fmt.Sprintf("            <td>%s</td>\n", escapedSubject))
	builder.WriteString("        </tr>\n")
	builder.WriteString("        <tr>\n")
	builder.WriteString("            <td><strong>Feedback Content:</strong></td>\n")
	builder.WriteString(fmt.Sprintf("            <td>%s</td>\n", escapedFeedbackContent))
	builder.WriteString("        </tr>\n")
	builder.WriteString("    </table>\n")
	builder.WriteString("</body>\n")
	builder.WriteString("</html>\n")

	return builder.String(), nil
}

// htmlEscape escapes special HTML characters to prevent XSS attacks
func htmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

func main() {
	// Example usage
	fromAddr := "noreply@example.com"
	toAddr := "support@example.com"
	userName := "John Doe"
	subject := "Bug Report"
	feedbackContent := "I found a bug in the login page. When I enter my password, nothing happens."

	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
		fmt.Printf("Error building email: %v\n", err)
		return
	}

	fmt.Println("Generated Email:")
	fmt.Println(emailBody)
