package main

import (
	"bytes"
	"fmt"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail constructs an HTML-formatted email body for user feedback.
// It takes the sender address, recipient address, username, subject, and feedback content,
// then returns the complete email body as a string and any error encountered.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate inputs
	if fromAddr == "" {
		return "", fmt.Errorf("fromAddr cannot be empty")
	}
	if toAddr == "" {
		return "", fmt.Errorf("toAddr cannot be empty")
	}
	if userName == "" {
		return "", fmt.Errorf("userName cannot be empty")
	}
	if subject == "" {
		return "", fmt.Errorf("subject cannot be empty")
	}
	if feedbackContent == "" {
		return "", fmt.Errorf("feedbackContent cannot be empty")
	}

	// Create the HTML email body
	var htmlBody bytes.Buffer
	htmlBody.WriteString("<!DOCTYPE html>\n")
	htmlBody.WriteString("<html>\n")
	htmlBody.WriteString("<head>\n")
	htmlBody.WriteString("  <meta charset=\"UTF-8\">\n")
	htmlBody.WriteString("  <title>User Feedback</title>\n")
	htmlBody.WriteString("</head>\n")
	htmlBody.WriteString("<body>\n")
	htmlBody.WriteString("  <h2>User Feedback Submission</h2>\n")
	htmlBody.WriteString("  <table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse: collapse; width: 100%; max-width: 600px;\">\n")
	htmlBody.WriteString("    <tr>\n")
	htmlBody.WriteString("      <td><strong>Username:</strong></td>\n")
	htmlBody.WriteString(fmt.Sprintf("      <td>%s</td>\n", escapeHTML(userName)))
	htmlBody.WriteString("    </tr>\n")
	htmlBody.WriteString("    <tr>\n")
	htmlBody.WriteString("      <td><strong>Subject:</strong></td>\n")
	htmlBody.WriteString(fmt.Sprintf("      <td>%s</td>\n", escapeHTML(subject)))
	htmlBody.WriteString("    </tr>\n")
	htmlBody.WriteString("    <tr>\n")
	htmlBody.WriteString("      <td><strong>Feedback Content:</strong></td>\n")
	htmlBody.WriteString(fmt.Sprintf("      <td>%s</td>\n", escapeHTML(feedbackContent)))
	htmlBody.WriteString("    </tr>\n")
	htmlBody.WriteString("  </table>\n")
	htmlBody.WriteString("</body>\n")
	htmlBody.WriteString("</html>\n")

	// Construct the full email with headers
	var emailBuffer bytes.Buffer
	emailBuffer.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	emailBuffer.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	emailBuffer.WriteString(fmt.Sprintf("Subject: User Feedback: %s\r\n", subject))
	emailBuffer.WriteString("MIME-Version: 1.0\r\n")
	emailBuffer.WriteString("Content-Type: text/html; charset=UTF-8\r\n")
	emailBuffer.WriteString("\r\n")
	emailBuffer.WriteString(htmlBody.String())

	return emailBuffer.String(), nil
}

// escapeHTML escapes special HTML characters to prevent XSS and ensure proper rendering
func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

func main() {
	// Example usage
	from := "noreply@example.com"
	to := "support@example.com"
	userName := "John Doe"
	subject := "Login Issue"
	feedbackContent := "I am unable to log in to my account. The password reset link is not working."

	emailBody, err := BuildFeedbackEmail(from, to, userName, subject, feedbackContent)
	if err != nil {
