<body>
    <div class="container">
        <div class="header">
            <h2>New User Feedback</h2>
        </div>
        <div class="content">
            <div class="field">
                <div class="label">Username:</div>
                <div class="value">%s</div>
            </div>
            <div class="field">
                <div class="label">Subject:</div>
                <div class="value">%s</div>
            </div>
