	formattedBody := fmt.Sprintf(htmlBody, safeUserName, safeSubject, safeFeedbackContent)

	// Construct the full email message with headers
	headers := make(map[string]string)
	headers["From"] = fromAddr
	headers["To"] = toAddr
	headers["Subject"] = subject
	headers["MIME-Version"] = "1.0"
	headers["Content-Type"] = "text/html; charset=UTF-8"

	// Build the header section
	var headerBuilder strings.Builder
	for key, value := range headers {
		headerBuilder.WriteString(fmt.Sprintf("%s: %s\r\n", key, value))
	}
	headerBuilder.WriteString("\r\n") // Blank line between headers and body

	// Combine headers and body
	emailBody = headerBuilder.String() + formattedBody

	return emailBody, nil
}

// escapeHTML escapes special HTML characters to prevent XSS attacks
func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

