func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate inputs
	if fromAddr == "" {
		return "", fmt.Errorf("from address cannot be empty")
	}
	if toAddr == "" {
		return "", fmt.Errorf("to address cannot be empty")
	}
	if userName == "" {
		return "", fmt.Errorf("user name cannot be empty")
	}
	if subject == "" {
		return "", fmt.Errorf("subject cannot be empty")
	}
	if feedbackContent == "" {
		return "", fmt.Errorf("feedback content cannot be empty")
	}

	// Construct MIME headers
	headers := make(map[string]string)
	headers["From"] = fromAddr
	headers["To"] = toAddr
	headers["Subject"] = subject
	headers["MIME-Version"] = "1.0"
	headers["Content-Type"] = "text/html; charset=UTF-8"

	// Build header string
	var headerStr string
	for key, value := range headers {
		headerStr += fmt.Sprintf("%s: %s\r\n", key, value)
	}

	// Construct HTML body
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>User Feedback</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            line-height: 1.6;
            color: #333;
        }
        .container {
            max-width: 600px;
            margin: 0 auto;
            padding: 20px;
            border: 1px solid #ddd;
            border-radius: 5px;
        }
        h1 {
            color: #2c3e50;
            border-bottom: 2px solid #3498db;
            padding-bottom: 10px;
        }
        .field {
            margin-bottom: 15px;
        }
        .label {
            font-weight: bold;
            color: #555;
        }
        .value {
            margin-top: 5px;
            white-space: pre-wrap;
            background-color: #f9f9f9;
            padding: 10px;
            border-radius: 3px;
            border-left: 3px solid #3498db;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>User Feedback Submission</h1>
        <div class="field">
            <span class="label">Username:</span>
            <div class="value">%s</div>
        </div>
        <div class="field">
            <span class="label">Subject:</span>
            <div class="value">%s</div>
        </div>
        <div class="field">
            <span class="label">Feedback Content:</span>
            <div class="value">%s</div>
        </div>
    </div>
</body>
</html>`, escapeHTML(userName), escapeHTML(subject), escapeHTML(feedbackContent))

	// Combine headers and body with proper separation
	emailBody = headerStr + "\r\n" + htmlBody

	return emailBody, nil
}

// escapeHTML escapes special HTML characters to prevent XSS and ensure proper display
func escapeHTML(s string) string {
	s = replaceAll(s, "&", "&amp;")
	s = replaceAll(s, "<", "&lt;")
	s = replaceAll(s, ">", "&gt;")
	s = replaceAll(s, "\"", "&quot;")
	s = replaceAll(s, "'", "&#39;")
	return s
}

// replaceAll replaces all occurrences of old with new in s
func replaceAll(s, old, new string) string {
	result := ""
	i := 0
	for i < len(s) {
		if i+len(old) <= len(s) && s[i:i+len(old)] == old {
			result += new
			i += len(old)
		} else {
			result += string(s[i])
			i++
		}
	}
	return result
}

func main() {
	// Example usage
	fromAddr := "noreply@example.com"
	toAddr := "support@example.com"
	userName := "John Doe"
	subject := "Bug Report: Login Issue"
	feedbackContent := "I am unable to log in to my account. The page shows a 500 error when I click submit."

