// BuildFeedbackEmail constructs an HTML-formatted email body for user feedback.
// It takes the sender address, recipient address, username, subject, and feedback content,
// and returns the complete email body as a string along with any error encountered.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate inputs
	if fromAddr == "" {
		return "", fmt.Errorf("from address cannot be empty")
	}
	if toAddr == "" {
		return "", fmt.Errorf("to address cannot be empty")
	}
	if userName == "" {
		return "", fmt.Errorf("user name cannot be empty")
	}
	if subject == "" {
		return "", fmt.Errorf("subject cannot be empty")
	}
	if feedbackContent == "" {
		return "", fmt.Errorf("feedback content cannot be empty")
	}

	// Escape HTML special characters in user-provided content to prevent XSS
	escapedUserName := htmlEscape(userName)
	escapedSubject := htmlEscape(subject)
	escapedFeedbackContent := htmlEscape(feedbackContent)

	// Construct the HTML email body
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>User Feedback</title>
</head>
<body>
    <h2>New User Feedback Received</h2>
    <table border="1" cellpadding="10" cellspacing="0" style="border-collapse: collapse; width: 100%%;">
        <tr>
            <td><strong>From:</strong></td>
            <td>%s</td>
        </tr>
        <tr>
            <td><strong>To:</strong></td>
            <td>%s</td>
        </tr>
        <tr>
            <td><strong>User Name:</strong></td>
            <td>%s</td>
        </tr>
        <tr>
            <td><strong>Subject:</strong></td>
            <td>%s</td>
        </tr>
        <tr>
            <td><strong>Feedback Content:</strong></td>
            <td>%s</td>
        </tr>
    </table>
</body>
</html>`, fromAddr, toAddr, escapedUserName, escapedSubject, escapedFeedbackContent)

	return htmlBody, nil
}

// htmlEscape escapes special HTML characters to prevent XSS attacks
func htmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

func main() {
	// Example usage
	fromAddr := "noreply@example.com"
	toAddr := "support@example.com"
	userName := "John Doe"
	subject := "Bug Report"
	feedbackContent := "I found a bug on the homepage when clicking the login button."

	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
		fmt.Printf("Error building email: %v\n", err)
		return
	}

	fmt.Println(emailBody)
}

